param([string]$GameRoot='F:/SteamLibrary/steamapps/common/RimWorld')
# Static source indexing only. Never loads or runs the target assembly.
$ErrorActionPreference='Stop'
$root=(Resolve-Path (Join-Path $PSScriptRoot '../..')).Path
$base=Join-Path $root 'docs/research/rimworld/evidence'
function Digest([string]$p){(Get-FileHash -LiteralPath $p).Hash.ToLowerInvariant()}
function TextDigest([string]$s){$h=[Security.Cryptography.SHA256]::Create();try{[Convert]::ToHexString($h.ComputeHash([Text.Encoding]::UTF8.GetBytes($s))).ToLowerInvariant()}finally{$h.Dispose()}}
function Source([string]$group,[string]$type,[int]$start,[int]$end){
 $m=Get-Content (Join-Path $base "$group-manifest.json") -Raw|ConvertFrom-Json
 $entries=@($m.types|Where-Object type -eq $type);if($entries.Count -ne 1){throw "Unknown type: $group/$type"};$t=$entries[0]
 $file=Join-Path $root $t.local_file
 if((Digest $file) -ne $t.sha256){throw "Changed source: $file"}
 if($start -lt 1 -or $end -lt $start -or $end -gt $t.lines){throw 'Invalid source range'}
 $lines=[IO.File]::ReadAllText($file).Split("`n")
 [ordered]@{group=$group;type=$type;file=$t.local_file;sha256=$t.sha256;lines=@($start,$end);excerpt_sha256=(TextDigest ($lines[($start-1)..($end-1)] -join "`n"))}
}
$claims=@(
 [ordered]@{id='CE01';kind='static-derived';finding='CaveGenParms.Default is modified by ordinary TileMutatorWorker_Caves: branchChance0.1 becomes0.02; allowBranchingAfterThisManyCells becomes10; width decrease0.034 and min1.4. IsRock requires in-bounds and generation Elevation>0.7. Cave scalar is not a3D height.';sources=@((Source 'caves-exploration' 'RimWorld.MapGenCavesUtility' 11 62),(Source 'generation' 'RimWorld.TileMutatorWorker_Caves' 11 53),(Source 'generation' 'RimWorld.TileMutatorWorker_Caves' 80 94))},
 [ordered]@{id='CE02';kind='static-derived';finding='Rock groups use flood fill, then GenMorphology.Open(group,6,map), whose internals are not reconstructed here. Disconnected subgroups smaller than300 or5% of the pre-filter group count are discarded; retained total needs300. Flood uses four cardinal directions.';sources=@((Source 'caves-exploration' 'RimWorld.MapGenCavesUtility' 74 95),(Source 'caves-exploration' 'RimWorld.MapGenCavesUtility' 130 133),(Source 'caves-exploration' 'RimWorld.MapGenCavesUtility' 373 400),(Source 'stonecutting' 'Verse.GenAdj' 33 79))},
 [ordered]@{id='CE03';kind='static-derived';finding='Open count: RoundRandom(N*U0.9..1.1*5.8/10000), cap3, then inclusive1..a if positive. Closed: density2.5, cap1, inclusive0..a. Reaching300 does not guarantee a cave. Starting attempts need not produce nonempty caves.';sources=@((Source 'caves-exploration' 'RimWorld.MapGenCavesUtility' 97 107),(Source 'caves-exploration' 'RimWorld.MapGenCavesUtility' 135 145),(Source 'generation' 'Verse.GenMath' 62 65));prior=@{file='generation-claims.json';ids=@('GN12','GN20')}},
 [ordered]@{id='CE04';kind='static-derived';finding='Open tunnels compare10 edge candidates by distance to existing cave up to40 and inward distance tie-break. Closed compare7 candidates up to30 treating outside space as cave. Width samples0.8..1 times curve(100,2),(300,4),(3000,5.5). Edge selection excludes distance<3 and existing caves, with random-group fallback.';sources=@((Source 'caves-exploration' 'RimWorld.MapGenCavesUtility' 41 62),(Source 'caves-exploration' 'RimWorld.MapGenCavesUtility' 108 127),(Source 'caves-exploration' 'RimWorld.MapGenCavesUtility' 143 206),(Source 'caves-exploration' 'RimWorld.MapGenCavesUtility' 355 371))},
 [ordered]@{id='CE05';kind='static-derived';finding='Dig advances continuous position by0.5 until a new cell, carves radius width/2, checks closed clearance width/2+1.5, attempts each side once after10 cells and width>1.8, angles40..90/-90..-40, tests6 directions with required depth18. Width decreases0.034 per entered cell; outside group, insufficient width or another tunnel stop it. Bridge cell limits diagonal gaps.';sources=@((Source 'caves-exploration' 'RimWorld.MapGenCavesUtility' 208 322))},
 [ordered]@{id='CE06';kind='static-derived';finding='GenStep_Fog first sets all fog, expands from player start or validated edge-reachable fallback, then explicit rootsToUnfog. Start blocker fallback searches radius5; no-start fallback searches center radius30 then edge/random. FogGrid is persistent NativeBitArray and is exposed as fogGrid. This is exploration state, not a sampled pawn-LOS radius.';sources=@((Source 'caves-exploration' 'RimWorld.GenStep_Fog' 7 56),(Source 'caves-exploration' 'Verse.FogGrid' 8 27))},
 [ordered]@{id='CE07';kind='static-derived';finding='FloodFillerFog passes unknown cells with no MakeFog edifice, without Walkable/Standable tests. Four-neighbor queue flood processes up to int.MaxValue, then reveals8-neighbor blocking boundary.500 is testMode-only. MakeFog means full fill. Border reveal is not propagation through opaque cells.';sources=@((Source 'caves-exploration' 'Verse.FloodFillerFog' 21 110),(Source 'caves-exploration-extra' 'Verse.FloodFiller' 50 145),(Source 'stonecutting' 'Verse.GenAdj' 33 79),(Source 'energy' 'Verse.ThingDef' 621 624))},
 [ordered]@{id='CE08';kind='static-derived';finding='Final mining strike calls DestroyMined then base.Destroy(KillFinalize). Building.DeSpawn removes edifice and for non-WillReplace MakeFog calls Notify_FogBlockerRemoved. Only Playing and at least one visible8-neighbor with no blocker or a door causes FloodUnfogAdjacent. Isolated unknown destruction does not reveal disconnected regions.';sources=@((Source 'generation' 'RimWorld.JobDriver_Mine' 108 115),(Source 'generation' 'RimWorld.Mineable' 36 46),(Source 'energy' 'Verse.Building' 175 222),(Source 'caves-exploration' 'Verse.FogGrid' 121 144),(Source 'caves-exploration' 'Verse.FogGrid' 208 244))},
 [ordered]@{id='CE09';kind='static-derived';finding='Door update calls entry notification at OpenPct>=0.4 with approachingPawn; player faction/host faction can unfog adjacent without area letter. Thing.Notify_Unfogged has beenRevealed guard, discovery/quest/letter side effects. Flood activates revealed pawns and can defer sleeping-assault lord wake. No native encounter probability is measured.';sources=@((Source 'housing' 'RimWorld.Building_Door' 386 401),(Source 'caves-exploration' 'Verse.FogGrid' 146 152),(Source 'energy' 'Verse.Thing' 1161 1181),(Source 'energy' 'Verse.Thing' 1295 1295),(Source 'caves-exploration' 'Verse.FloodFillerFog' 83 136))},
 [ordered]@{id='CE10';kind='static-derived';finding='Mine cell designation checks bounds/duplicate before accepting fogged cells directly. Known cells require actual mineable. UnfogWorker deletes Mine designation only when a formerly fogged cell has no Mineable. A blind mining line is not evidence of hidden ore or a valid worker job.';sources=@((Source 'caves-exploration' 'RimWorld.Designator_Mine' 31 84),(Source 'caves-exploration' 'Verse.FogGrid' 48 68))},
 [ordered]@{id='CE11';kind='static-derived-bounded-search';finding='Mining candidates need Mine/MineVein designation, adjacent Walkable cell and actual Mineable. Jobs require reservation/history permission and immediate Touch work face or obstruction-hauling fallback. Scanner default disallows unreachable; JobGiver_Work rejects forbidden and chooses reachable target. Miner uses Danger.Deadly and job expiry20000, not fixed mining duration. No direct fog condition in the four inspected mining/scanner classes; this does not exclude unseen callers or mods.';sources=@((Source 'caves-exploration-extra' 'RimWorld.MineAIUtility' 20 107),(Source 'caves-exploration' 'RimWorld.WorkGiver_Miner' 7 33),(Source 'work' 'RimWorld.WorkGiver_Scanner' 9 39),(Source 'work' 'RimWorld.JobGiver_Work' 116 156),(Source 'work' 'RimWorld.JobGiver_Work' 219 226))},
 [ordered]@{id='CE12';kind='static-derived';finding='Plan_Add accepts in-bounds non-no-build-edge cells without a fog test. Build normal path delegates to GenConstruct, which rejects fogged center with CannotPlaceInUndiscovered after footprint bounds/edge validation. Center fog check is not an every-footprint-cell fog check; abstract plan is not blueprint.';sources=@((Source 'caves-exploration-extra' 'RimWorld.Designator_Plan_Add' 101 112),(Source 'caves-exploration-extra' 'RimWorld.Designator_Build' 446 453),(Source 'skills' 'RimWorld.GenConstruct' 364 385))},
 [ordered]@{id='CE13';kind='static-derived';finding='Map-click selection needs selectable, non-hidden pawn, spawned parent and at least one nonfog occupied cell. Selector calls this utility. SelectableByHotkey checks selectable/Spawned but not fog; do not universalize map-click restrictions to all selection APIs.';sources=@((Source 'caves-exploration' 'RimWorld.ThingSelectionUtility' 19 55),(Source 'caves-exploration' 'RimWorld.Selector' 566 580))},
 [ordered]@{id='CE14';kind='static-derived';finding='Area revealed letter: mechanoid gives ThreatBig, otherwise !allOnScreen or cellsUnfogged>=600 gives neutral letter.600 is notification threshold; count excludes later blocker-boundary reveal. FloodUnfogAdjacent overwrites the result per component rather than summing multiple components.';sources=@((Source 'caves-exploration' 'Verse.FogGrid' 168 256),(Source 'caves-exploration' 'Verse.FloodFillerFog' 36 57),(Source 'caves-exploration' 'Verse.FloodFillerFog' 83 109))},
 [ordered]@{id='CE15';kind='static-derived-and-arithmetic';finding='FogGrid is one persistent bit per map cell and exposes Refog(CellRect); debug all-map refog also exists. Ordinary inspected reveal paths do not refog when pawns leave; all Refog callers were not enumerated.250*250 bits need7813 bytes and64*64*16 bits need8192 bytes before allocator/storage/render overhead; these are payload calculations, not measured RAM.';sources=@((Source 'caves-exploration' 'Verse.FogGrid' 18 27),(Source 'caves-exploration' 'Verse.FogGrid' 100 119),(Source 'caves-exploration' 'Verse.FloodFillerFog' 138 158))},
 [ordered]@{id='CE16';kind='project-adaptation-guidance';finding='Web3D should separate true world, player knowledge and visible slice; persist exploration and gate picking/overlays/public views consistently. Cross-floor connectivity, sealed chambers and three-cell headroom are project choices, not original2D cave generator equivalence. Worker fog gates require explicit adaptation labeling.';sources=@()}
)
$groups=@('caves-exploration','caves-exploration-extra','generation','energy','housing','skills','work','stonecutting')
$deps=@($groups|ForEach-Object{"docs/research/rimworld/evidence/$_-manifest.json"})+@(
 'docs/research/rimworld/evidence/caves-exploration-types.json','docs/research/rimworld/evidence/caves-exploration-extra-types.json',
 'docs/research/rimworld/evidence/generation-claims.json','docs/research/rimworld/06-world-generation-resources.md','docs/research/rimworld/108-caves-exploration-mechanisms.md',
 'scripts/research/collect-caves-exploration-evidence.ps1','scripts/research/verify-caves-exploration-evidence.mjs'
)
$m=Get-Content (Join-Path $base 'caves-exploration-manifest.json') -Raw|ConvertFrom-Json
if((Digest (Join-Path $GameRoot 'Assembly-CSharp.dll')) -ne $m.source_sha256){throw 'Installed assembly differs from recorded source'}
$rooms=@('#########','#...#...#','#...#...#','#########')
$cases=@(
 [ordered]@{id='CG01';name='closed-two-rooms';grid=$rooms;actions=@(@{op='flood';at=@(1,1)});expected_known=20;known=@(,@(4,1));hidden=@(,@(5,1));markers=@();remaining_markers=@()},
 [ordered]@{id='CG02';name='breakthrough-connected-room';grid=$rooms;actions=@(@{op='flood';at=@(1,1)},@{op='remove';at=@(4,1)});expected_known=36;known=@(,@(7,2));hidden=@();markers=@();remaining_markers=@()},
 [ordered]@{id='CG03';name='unknown-isolated-removal';grid=$rooms;actions=@(@{op='remove';at=@(4,1)});expected_known=0;known=@();hidden=@(@(4,1),@(1,1),@(7,2));markers=@();remaining_markers=@()},
 [ordered]@{id='CG04';name='diagonal-is-not-connected';grid=@('#####','#.###','##.##','#####');actions=@(@{op='flood';at=@(1,1)});expected_known=8;known=@(,@(2,1));hidden=@(,@(2,2));markers=@();remaining_markers=@()},
 [ordered]@{id='CG05';name='nonstandable-water-does-not-block';grid=@('#######','#.~...#','#######');actions=@(@{op='flood';at=@(1,1)});expected_known=21;known=@(@(2,1),@(5,1));hidden=@();markers=@();remaining_markers=@()},
 [ordered]@{id='CG06';name='reveal-clears-only-invalid-blind-mine';grid=$rooms;actions=@(@{op='flood';at=@(1,1)});expected_known=20;known=@(@(1,1),@(4,1));hidden=@(,@(5,1));markers=@(@(1,1),@(4,1),@(5,1));remaining_markers=@('4,1','5,1')}
)
$e=[ordered]@{
 schema_version=1;evidence_id='RW17-CAVES-EXPLORATION-AUDIT';date_local='2026-11-04';version_text=$m.version_text;source_sha256=$m.source_sha256;engine_version=$m.engine_version;engine_sha256=$m.engine_sha256
 manifests=$groups;new_groups=@('caves-exploration','caves-exploration-extra');new_type_count=14
 dependencies=@(foreach($p in $deps){[ordered]@{file=$p;sha256=(Digest (Join-Path $root $p))}});claims=$claims
 parameters=[ordered]@{open_per_10000=5.8;closed_per_10000=2.5;max_open=3;max_closed=1;min_rock_cells=300;subgroup_fraction=0.05;default_branch_chance=0.1;ordinary_branch_chance=0.02;branch_after_cells=10;width_decay=0.034;min_width=1.4;branch_width_offset=@(0.2,0.4);width_curve=@(@(100,2),@(300,4),@(3000,5.5));open_candidates=10;closed_candidates=7;open_distance_cap=40;closed_distance_cap=30;continuous_step=0.5;branch_candidates=6;branch_min_depth=18;area_letter_threshold=600;mining_job_expiry=20000}
 graph_cases=$cases
 model_scope='Independent 2D one-cell opaque/air graph explanation; not executed game methods, native replay, full geometry, NPC logic or Web implementation equivalence. Hash signs represent mineable full blockers, dots air and tilde nonstandable non-blocker.'
 count_cases=@(
  [ordered]@{n=300;factor=1;kind='open';round_fraction=0.5;chosen_count=0;expected_raw=0.174;expected_cap=0},
  [ordered]@{n=300;factor=1;kind='open';round_fraction=0.1;chosen_count=1;expected_raw=0.174;expected_cap=1},
  [ordered]@{n=10000;factor=1;kind='open';round_fraction=0.9;chosen_count=2;expected_raw=5.8;expected_cap=3},
  [ordered]@{n=300;factor=1;kind='closed';round_fraction=0.01;chosen_count=0;expected_raw=0.075;expected_cap=1},
  [ordered]@{n=300;factor=1;kind='closed';round_fraction=0.01;chosen_count=1;expected_raw=0.075;expected_cap=1}
 )
 memory_cases=@(@{dimensions=@(250,250);cells=62500;bit_payload_bytes=7813;byte_payload_bytes=62500},@{dimensions=@(64,64,16);cells=65536;bit_payload_bytes=8192;byte_payload_bytes=65536})
 runtime=[ordered]@{new_native_runs=0;game_methods_executed=$false;native_screenshots=0;new_save_samples=0;reason='Static questions answered by bounded source tracing plus independent examples; no runtime-equivalence claim.'}
 limitations=@('GenMorphology.Open and exact noise/RNG implementation are not reconstructed.','No enabled-mod or effective-Def database validation.','Not all Refog callers or selection APIs are traced.','One-cell toy graph does not model multi-cell edifices, door timing, encounter AI or callbacks.','No original world seed replay, cave-generation equivalence, benchmark or measured memory result.','Web three-dimensional sealed chambers, headroom and cross-floor rules are project adaptations.','Full derived source remains local; neither game assemblies nor proprietary assets are published here.')
}
[IO.File]::WriteAllText((Join-Path $base 'caves-exploration-evidence.json'),($e|ConvertTo-Json -Depth 20).Replace("`r`n","`n")+"`n",[Text.UTF8Encoding]::new($false))
"Indexed $($claims.Count) claims, $($deps.Count) dependencies and $($cases.Count) independent graph cases; no native execution."
